```rust
#[verus_spec(
    invariant
        v@ =~= Seq::new(i as nat, |k| k as u32),
)]
for i in 0..n {
    v.push(i);
}
```

```rust
#[verus_spec(
    invariant i <= 10,
)]
while i < 10 {
    i = i + 1;
}
```

```rust
#[verus_spec(
    invariant i <= 10,
    invariant_except_break i <= 9,
    ensures i == 10, ret == 10,
)]
loop {
    i = i + 1;
    if i == 10 { ret = i; break; }
}
```

